import Foundation
import UIKit

/// In-memory backend with a real sample of museum works (DemoLibrary.json,
/// generated by the server's importer). Lets the app be explored before a
/// frame server exists. Images come from Resources/DemoImages (originals and
/// their e-paper look rendered by the server pipeline, framed on the phone by
/// DemoFraming), falling back to the museums' CDNs.
actor DemoBackend: FrameBackend {
    nonisolated var isDemo: Bool { true }

    private struct DemoFile: Decodable {
        let items: [Item]
        let playlists: [Playlist]
        /// Crops the server's interest analysis chose: item id -> orientation -> crops.
        var framing: [String: [String: DemoFraming.Crops]]?
        /// The "picture" mat the server picks for each work (#rrggbb, screen colours).
        var tints: [String: String]?
    }

    private var items: [Item]
    private var playlistsByID: [Int: Playlist]
    private var settingsValue = FrameSettings.defaults
    private var queue: [String] = []
    private var history: [String] = []
    private var currentID: String?
    private var holdValue: Hold?
    private struct ImageURLs: Sendable {
        let thumb: URL?
        let image: URL?
    }

    private let imageURLs: [String: ImageURLs]
    /// Remote museum URL -> item id, so search results also use bundled files.
    private let idsByURL: [URL: String]
    private let arts: [String: DemoFraming.Art]
    private let autoCrops: [String: [String: DemoFraming.Crops]]
    /// Settings and crop corrections as last saved, for nonisolated image requests.
    private let shared = FramingState()
    private var framingRevision = 0

    init() {
        let loaded = Self.load()
        items = loaded.items
        var byID: [Int: Playlist] = [:]
        for (index, playlist) in loaded.playlists.enumerated() {
            var copy = playlist
            copy.id = index + 1
            byID[index + 1] = copy
        }
        playlistsByID = byID
        imageURLs = Dictionary(
            uniqueKeysWithValues: loaded.items.map {
                ($0.id, ImageURLs(thumb: URL(string: $0.thumbUrl), image: URL(string: $0.imageUrl)))
            }
        )
        var byURL: [URL: String] = [:]
        for (id, urls) in imageURLs {
            for url in [urls.thumb, urls.image].compactMap({ $0 }) { byURL[url] = id }
        }
        idsByURL = byURL
        arts = Dictionary(
            uniqueKeysWithValues: loaded.items.map {
                ($0.id, DemoFraming.Art(
                    caption: DemoFraming.caption(for: $0), text: DemoFraming.textBlock(for: $0),
                    isPhoto: $0.kind == .photo, tint: loaded.tints?[$0.id].flatMap(DemoFraming.color(hex:))
                ))
            }
        )
        autoCrops = loaded.framing ?? [:]
        // Start out playing the first playlist, like a fresh server does.
        settingsValue.playlistId = 1
        if let fit = LaunchRoute.fit { settingsValue.art.fit = fit }
        if let mat = LaunchRoute.mat { settingsValue.art.mat = mat }
        let first = byID[1].map { playlist in
            Self.sorted(loaded.items.filter { Self.matches($0, playlist.rules) }, by: "suitability")
        }
        queue = (first.flatMap { $0.isEmpty ? nil : $0 } ?? loaded.items).map(\.id)
        currentID = queue.first
        if !queue.isEmpty { queue.removeFirst() }
        shared.current = settingsValue
    }

    private static func load() -> DemoFile {
        guard
            let url = Bundle.main.url(forResource: "DemoLibrary", withExtension: "json"),
            let data = try? Data(contentsOf: url),
            let file = try? LiveBackend.decoder().decode(DemoFile.self, from: data)
        else { return DemoFile(items: [], playlists: [], framing: nil, tints: nil) }
        return file
    }

    // MARK: Matching (mirrors server/src/frame_server/library/repo.py)

    private static func matches(_ item: Item, _ rules: PlaylistRules) -> Bool {
        if item.excluded { return false }
        if rules.favoritesOnly && !item.favorite { return false }
        if !rules.kinds.isEmpty && !rules.kinds.contains(item.kind) { return false }
        if !rules.artists.isEmpty
            && !rules.artists.contains(where: { $0.caseInsensitiveCompare(item.artist) == .orderedSame })
        {
            return false
        }
        func overlaps(_ a: [String], _ b: [String]) -> Bool {
            Set(a.map { $0.lowercased() }).intersection(b.map { $0.lowercased() }).isEmpty == false
        }
        if !rules.styles.isEmpty && !overlaps(item.styles, rules.styles) { return false }
        if !rules.subjects.isEmpty && !overlaps(item.subjects, rules.subjects) { return false }
        if !rules.colors.isEmpty && Set(item.colorTags).isDisjoint(with: rules.colors) { return false }
        if let from = rules.yearFrom, (item.year ?? Int.min) < from { return false }
        if let to = rules.yearTo, (item.year ?? Int.max) > to { return false }
        if let minimum = rules.minSuitability, (item.suitability ?? 0) < minimum { return false }
        if !rules.query.isEmpty {
            let haystack = ([item.title, item.artist, item.medium, item.classification, item.culture]
                + item.styles + item.subjects).joined(separator: " ").lowercased()
            for word in rules.query.lowercased().split(separator: " ") where !haystack.contains(word) {
                return false
            }
        }
        return true
    }

    private static func sorted(_ list: [Item], by sort: String) -> [Item] {
        switch sort {
        case "title": list.sorted { $0.title < $1.title }
        case "year": list.sorted { ($0.year ?? 0) < ($1.year ?? 0) }
        case "recent": list.sorted { $0.addedAt > $1.addedAt }
        case "suitability": list.sorted { ($0.suitability ?? 0) > ($1.suitability ?? 0) }
        default: list.sorted { ($0.artist, $0.year ?? 0) < ($1.artist, $1.year ?? 0) }
        }
    }

    private func items(for playlist: Playlist) -> [Item] {
        if playlist.kind == .manual {
            return playlist.itemIds.compactMap { id in items.first { $0.id == id } }
        }
        return Self.sorted(items.filter { Self.matches($0, playlist.rules) }, by: "suitability")
    }

    private func summary(_ playlist: Playlist) -> PlaylistSummary {
        let list = items(for: playlist)
        return PlaylistSummary(
            id: playlist.id ?? 0, name: playlist.name, description: playlist.description,
            kind: playlist.kind, rules: playlist.rules, itemCount: list.count,
            coverItemIds: list.prefix(4).map(\.id)
        )
    }

    private func detail(_ playlist: Playlist) -> PlaylistDetail {
        PlaylistDetail(
            playlist: summary(playlist), itemIds: playlist.itemIds,
            items: items(for: playlist).map(\.summary)
        )
    }

    // MARK: Player & status

    func health() async throws -> Health { Health(ok: true, version: "demo", palette: "spectra6-reference") }

    func status(refresh: Bool) async throws -> StatusView {
        let now = ISO8601DateFormatter().string(from: .now)
        let device = DeviceStatus(
            configured: true, reachable: true, checkedAt: now, lastSeen: now, batteryLevel: 76,
            charging: false, powerSource: "battery", batteryRaw: nil, networkStandby: true,
            firmware: "S-RSEDWWC-1050.1", model: "EM32DX", serial: "DEMO0001", name: "Salon",
            error: nil, lastPushAt: now, lastFetchAt: now
        )
        let server = ServerStatus(
            version: "demo", uptimeS: 3600, libraryCount: items.count,
            playlists: playlistsByID.count, jobsRunning: 0, palette: "spectra6-reference"
        )
        return StatusView(device: device, server: server)
    }

    func player() async throws -> PlayerView {
        let current = currentID.flatMap { id in items.first { $0.id == id } }
        let playlist = settingsValue.playlistId.flatMap { playlistsByID[$0] }.map(summary)
        let nowShowing = current.map {
            NowShowing(
                title: $0.title, description: "\($0.artist) — \($0.title)", source: $0.source,
                created: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
                previewUrl: "/demo/\($0.id)?\(settingsValue.presentationKey)|\(framingRevision)", item: $0
            )
        }
        let next = Calendar.current.nextDate(
            after: .now, matching: DateComponents(hour: 7, minute: 0), matchingPolicy: .nextTime
        )
        return PlayerView(
            mode: settingsValue.mode, playlist: playlist, current: nowShowing,
            upcoming: queue.prefix(8).compactMap { id in items.first { $0.id == id }?.summary },
            history: history.suffix(8).reversed().compactMap { id in items.first { $0.id == id }?.summary },
            hold: holdValue,
            lastChangeAt: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-5400)),
            nextChangeAt: next.map { ISO8601DateFormatter().string(from: $0) },
            busy: false, lastError: nil
        )
    }

    func next() async throws {
        guard !queue.isEmpty else { return }
        if let currentID { history.append(currentID) }
        currentID = queue.removeFirst()
        holdValue = nil
    }

    func previous() async throws {
        guard let previous = history.popLast() else { return }
        if let currentID { queue.insert(currentID, at: 0) }
        currentID = previous
        holdValue = nil
    }

    func hold(_ spec: HoldSpec) async throws -> PlayerView {
        switch spec {
        case .untilNextChange: holdValue = nil
        case .forever: holdValue = Hold(until: nil, forever: true)
        default:
            let minutes = Double(spec.wireValue) ?? 60
            holdValue = Hold(
                until: ISO8601DateFormatter().string(from: .now.addingTimeInterval(minutes * 60)),
                forever: false
            )
        }
        return try await player()
    }

    func releaseHold() async throws -> PlayerView {
        holdValue = nil
        return try await player()
    }

    // MARK: Library

    func items(_ query: LibraryQuery) async throws -> ItemPage {
        let rules = PlaylistRules(
            query: query.text, artists: query.artists, styles: query.styles, subjects: query.subjects,
            colors: query.colors, kinds: query.kinds, favoritesOnly: query.favoritesOnly
        )
        let list = Self.sorted(items.filter { Self.matches($0, rules) }, by: query.sort)
        let page = list.dropFirst(query.offset).prefix(query.limit)
        return ItemPage(total: list.count, items: page.map(\.summary))
    }

    func item(id: String) async throws -> Item {
        guard let item = items.first(where: { $0.id == id }) else { throw BackendError.notFound }
        return item
    }

    private func update(_ id: String, _ change: (inout Item) -> Void) throws -> Item {
        guard let index = items.firstIndex(where: { $0.id == id }) else { throw BackendError.notFound }
        change(&items[index])
        return items[index]
    }

    func setFavorite(id: String, _ favorite: Bool) async throws -> Item {
        try update(id) { $0.favorite = favorite }
    }

    func setExcluded(id: String, _ excluded: Bool) async throws -> Item {
        try update(id) { $0.excluded = excluded }
    }

    func show(itemID: String, hold: HoldSpec) async throws {
        if let currentID { history.append(currentID) }
        currentID = itemID
        queue.removeAll { $0 == itemID }
        _ = try await self.hold(hold)
    }

    // MARK: Framing

    func framing(itemID: String, orientation: String) async throws -> FramingView {
        guard let item = items.first(where: { $0.id == itemID }),
              let size = DemoFraming.pixelSize(itemID)
        else { throw BackendError.notFound }
        let pres = item.kind == .photo ? settingsValue.photo : settingsValue.art
        let custom = shared.crops[itemID]?[orientation]
        let plan = DemoFraming.plan(
            size, canvas: DemoFraming.canvas(orientation), presentation: pres,
            caption: pres.label, crops: crops(itemID, orientation)
        )
        let isCustom = switch plan.fit {
        case "fill": custom?.fill != nil
        case "details": custom?.details != nil
        case "description": custom?.detail != nil
        case "fit": custom?.fit != nil
        default: false
        }
        let windows = plan.windows.compactMap { window -> FramingWindow? in
            guard let crop = window.crop else { return nil }
            return FramingWindow(role: window.role, aspect: window.rect.width / window.rect.height, crop: crop, custom: isCustom)
        }
        return FramingView(orientation: orientation, fit: plan.fit, width: Int(size.width), height: Int(size.height), windows: windows)
    }

    func saveFraming(itemID: String, orientation: String, crops: [Crop]) async throws -> FramingView {
        let current = try await framing(itemID: itemID, orientation: orientation)
        var saved = shared.crops[itemID]?[orientation] ?? DemoFraming.Crops()
        switch (current.fit, crops.count) {
        case ("fill", 1): saved.fill = crops[0]
        case ("details", 2): saved.details = crops
        case ("description", 1): saved.detail = crops[0]
        case ("fit", 1): saved.fit = crops[0]
        default: throw BackendError.http(status: 422, body: "")
        }
        shared.crops[itemID, default: [:]][orientation] = saved
        framingRevision += 1
        return try await framing(itemID: itemID, orientation: orientation)
    }

    func resetFraming(itemID: String, orientation: String) async throws -> FramingView {
        // Only the current mode's crop goes back to automatic.
        let current = try await framing(itemID: itemID, orientation: orientation)
        var saved = shared.crops[itemID]?[orientation] ?? DemoFraming.Crops()
        switch current.fit {
        case "fill": saved.fill = nil
        case "details": saved.details = nil
        case "description": saved.detail = nil
        default: saved.fit = nil
        }
        shared.crops[itemID, default: [:]][orientation] = saved
        framingRevision += 1
        return try await framing(itemID: itemID, orientation: orientation)
    }

    /// The user's correction, else what the server's analysis chose.
    private nonisolated func crops(_ id: String, _ orientation: String) -> DemoFraming.Crops? {
        let auto = autoCrops[id]?[orientation]
        guard let custom = shared.crops[id]?[orientation] else { return auto }
        return DemoFraming.Crops(
            fill: custom.fill ?? auto?.fill, details: custom.details ?? auto?.details,
            detail: custom.detail ?? auto?.detail, fit: custom.fit
        )
    }

    func facets() async throws -> Facets {
        func top(_ values: [String]) -> [FacetValue] {
            Dictionary(values.map { ($0, 1) }, uniquingKeysWith: +)
                .filter { !$0.key.isEmpty }
                .map { FacetValue(value: $0.key, count: $0.value) }
                .sorted { ($0.count, $1.value) > ($1.count, $0.value) }
        }
        let visible = items.filter { !$0.excluded }
        return Facets(
            artists: top(visible.map(\.artist)),
            styles: top(visible.flatMap(\.styles)),
            subjects: top(visible.flatMap(\.subjects)),
            colors: top(visible.flatMap(\.colorTags)),
            sources: top(visible.map(\.source)),
            kinds: top(visible.map(\.kind.rawValue))
        )
    }

    // MARK: Playlists

    func playlists() async throws -> [PlaylistSummary] {
        playlistsByID.keys.sorted().compactMap { playlistsByID[$0] }.map(summary)
    }

    func playlist(id: Int) async throws -> PlaylistDetail {
        guard let playlist = playlistsByID[id] else { throw BackendError.notFound }
        return detail(playlist)
    }

    func savePlaylist(_ playlist: Playlist) async throws -> PlaylistDetail {
        var copy = playlist
        if copy.id == nil { copy.id = (playlistsByID.keys.max() ?? 0) + 1 }
        playlistsByID[copy.id!] = copy
        return detail(copy)
    }

    func deletePlaylist(id: Int) async throws { playlistsByID[id] = nil }

    func addToPlaylist(id: Int, itemIDs: [String]) async throws -> PlaylistDetail {
        guard var playlist = playlistsByID[id] else { throw BackendError.notFound }
        playlist.itemIds += itemIDs.filter { !playlist.itemIds.contains($0) }
        playlistsByID[id] = playlist
        return detail(playlist)
    }

    func previewRules(_ rules: PlaylistRules) async throws -> RulesPreview {
        let list = Self.sorted(items.filter { Self.matches($0, rules) }, by: "suitability")
        return RulesPreview(count: list.count, items: list.prefix(24).map(\.summary))
    }

    func play(playlistID: Int) async throws {
        guard let playlist = playlistsByID[playlistID] else { throw BackendError.notFound }
        settingsValue.playlistId = playlistID
        settingsValue.mode = "art"
        queue = items(for: playlist).map(\.id).shuffled()
        try await next()
    }

    // MARK: Settings, museums, device

    func settings() async throws -> FrameSettings { settingsValue }

    func saveSettings(_ settings: FrameSettings) async throws -> FrameSettings {
        settingsValue = settings
        shared.current = settings
        return settings
    }

    func museums() async throws -> [Museum] {
        [
            Museum(key: "aic", name: "Art Institute of Chicago"),
            Museum(key: "cma", name: "Cleveland Museum of Art"),
            Museum(key: "met", name: "The Metropolitan Museum of Art"),
            Museum(key: "wmc", name: "Wikimedia Commons"),
        ]
    }

    func searchMuseum(source: String, query: String, page: Int) async throws -> RemotePage {
        let rules = PlaylistRules(query: query)
        let found = items.filter { $0.source == source && Self.matches($0, rules) }
        return RemotePage(total: found.count, items: found.map { RemoteItem(item: $0, inLibrary: true) })
    }

    func importArtwork(source: String, sourceID: String) async throws -> Item {
        guard let item = items.first(where: { $0.source == source && $0.sourceId == sourceID }) else {
            throw BackendError.notFound
        }
        return item
    }

    func album() async throws -> AlbumInfo {
        AlbumInfo(
            url: settingsValue.albumUrl,
            lastSync: AlbumSync(
                at: ISO8601DateFormatter().string(from: .now.addingTimeInterval(-1800)), count: 0,
                name: "Rodzina"
            ),
            photos: 0
        )
    }

    func syncAlbum() async throws {}

    func uploadPhoto(_ upload: PhotoUpload) async throws -> Item {
        try await Task.sleep(for: .milliseconds(300))
        let id = "upload:" + UUID().uuidString.prefix(12).lowercased()
        let file = DemoFraming.uploadURL(id)
        guard let image = UIImage(data: upload.data)?.cgImage else { throw BackendError.invalidResponse }
        try FileManager.default.createDirectory(at: file.deletingLastPathComponent(), withIntermediateDirectories: true)
        try upload.data.write(to: file, options: .atomic)
        let item = Item(
            id: id, kind: .photo, source: "upload", sourceId: "", title: upload.title, artist: "",
            artistBio: "", dateText: String((upload.takenAt ?? "").prefix(10)),
            year: upload.takenAt.flatMap { Int($0.prefix(4)) }, medium: "", classification: "",
            styles: [], subjects: [], culture: "", museum: "", credit: "", license: "", url: "",
            description: "", imageUrl: "", thumbUrl: "", width: image.width, height: image.height,
            colors: [], colorTags: [], suitability: nil, favorite: false, excluded: false,
            addedAt: ISO8601DateFormatter().string(from: .now), lastShownAt: nil, showCount: 0,
            photo: PhotoInfo(takenAt: upload.takenAt, latitude: upload.latitude, longitude: upload.longitude)
        )
        items.append(item)
        shared.uploads[id] = DemoFraming.Art(
            caption: DemoFraming.caption(for: item), text: DemoFraming.textBlock(for: item),
            isPhoto: true, tint: DemoFraming.tint(of: image)
        )
        return item
    }

    func sendPhoto(_ data: Data, title: String, preset: String, hold: HoldSpec) async throws -> DisplayResponse {
        try await Task.sleep(for: .seconds(1.5))
        return DisplayResponse(pushed: true, fetched: true, message: nil)
    }

    func wake() async throws {}
    func sleep() async throws {}

    // MARK: Images

    nonisolated func request(for image: ImageRef) -> URLRequest? {
        let url: URL?
        switch image {
        case let .thumb(id): url = Self.bundled(id) ?? imageURLs[id]?.thumb
        case let .image(id): url = Self.bundled(id) ?? imageURLs[id]?.image ?? imageURLs[id]?.thumb
        case let .framePreview(id, settings):
            url = framed(id, settings) ?? Self.bundled(id) ?? imageURLs[id]?.thumb
        case let .path(path):
            // "/demo/<id>?<presentation key>"; the key only makes the path change.
            let id = String(path.dropFirst("/demo/".count).prefix { $0 != "?" })
            url = framed(id) ?? Self.bundled(id) ?? imageURLs[id]?.image
        case let .url(remote): url = idsByURL[remote].flatMap { Self.bundled($0) } ?? remote
        }
        return url.map { URLRequest(url: $0, timeoutInterval: 60) }
    }

    private nonisolated func framed(_ id: String, _ settings: FrameSettings? = nil) -> URL? {
        let settings = settings ?? shared.current
        return (arts[id] ?? shared.uploads[id]).flatMap {
            DemoFraming.framed(id, art: $0, settings: settings, crops: crops(id, settings.orientation))
        }
    }

    /// Resources/DemoImages/<stem>.jpg
    private static func bundled(_ id: String) -> URL? {
        if let url = Bundle.main.url(forResource: DemoFraming.stem(id), withExtension: "jpg") { return url }
        let upload = DemoFraming.uploadURL(id)
        return FileManager.default.fileExists(atPath: upload.path) ? upload : nil
    }
}

/// Lock-guarded settings and crop corrections for image requests, which run
/// outside the actor.
private final class FramingState: @unchecked Sendable {
    private let lock = NSLock()
    private var value = FrameSettings.defaults
    private var corrections: [String: [String: DemoFraming.Crops]] = [:]

    var current: FrameSettings {
        get { lock.withLock { value } }
        set { lock.withLock { value = newValue } }
    }

    /// Item id -> orientation -> the user's crops.
    var crops: [String: [String: DemoFraming.Crops]] {
        get { lock.withLock { corrections } }
        set { lock.withLock { corrections = newValue } }
    }

    private var uploaded: [String: DemoFraming.Art] = [:]

    /// Photos "uploaded" in this demo session.
    var uploads: [String: DemoFraming.Art] {
        get { lock.withLock { uploaded } }
        set { lock.withLock { uploaded = newValue } }
    }
}
